import { OutlineNode, OutlineRow, OutlineTree } from "./solution";

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function row(actual: OutlineRow, id: string, label: string, kind: string, depth: number, expanded: boolean, selected: boolean): void {
  equal(actual.id, id, `${id} id`);
  equal(actual.label, label, `${id} label`);
  equal(actual.kind, kind, `${id} kind`);
  equal(actual.depth, depth, `${id} depth`);
  equal(actual.expanded, expanded, `${id} expanded`);
  equal(actual.selected, selected, `${id} selected`);
  assert(Object.isFrozen(actual), `${id} row is frozen`);
}
function expectTypeError(action: () => void, message: string): void {
  let thrown: unknown;
  try { action(); } catch (error) { thrown = error; }
  assert(thrown instanceof TypeError, message);
}

const child = { id: "child", label: "Child", kind: "page", children: [] as OutlineNode[] };
const root = { id: "root", label: "Root", kind: "folder", children: [child] };
const second = { id: "second", label: "Second", kind: "page" };
const tree = new OutlineTree([root, second]);
root.label = "Mutated";
child.label = "Mutated child";
root.children.length = 0;

let rows = tree.visibleRows();
equal(rows.length, 2, "collapsed tree shows roots only");
row(rows[0], "root", "Root", "folder", 0, false, false);
row(rows[1], "second", "Second", "page", 0, false, false);
assert(rows !== tree.visibleRows(), "visibleRows returns a new array");

equal(tree.toggle("missing"), false, "unknown toggle returns false");
equal(tree.toggle("root"), true, "known node expands");
rows = tree.visibleRows();
equal(rows.length, 3, "expanded parent reveals child");
row(rows[0], "root", "Root", "folder", 0, true, false);
row(rows[1], "child", "Child", "page", 1, false, false);
row(rows[2], "second", "Second", "page", 0, false, false);
equal(tree.toggle("root"), false, "second toggle collapses");

const events: string[] = [];
let added = false;
let unsubscribeSecond: () => void = () => {};
tree.onSelection(id => {
  events.push(`first:${id}`);
  unsubscribeSecond();
  if (!added) {
    added = true;
    tree.onSelection(later => { events.push(`third:${later}`); });
  }
});
unsubscribeSecond = tree.onSelection(id => { events.push(`second:${id}`); });
equal(events.length, 0, "subscription is not immediate");
equal(tree.select("missing"), false, "unknown selection returns false");
equal(events.length, 0, "unknown selection does not notify");
equal(tree.select("child"), true, "known selection succeeds");
equal(events.join("|"), "first:child|second:child", "selection uses listener snapshot and order");
unsubscribeSecond();
unsubscribeSecond();
equal(tree.select("root"), true, "second known selection succeeds");
equal(events.join("|"), "first:child|second:child|first:root|third:root", "listener changes affect later selection only");

const throwing = new OutlineTree([{ id: "x", label: "X", kind: "page" }]);
const marker = new Error("stop");
let laterCalled = false;
throwing.onSelection(() => { throw marker; });
throwing.onSelection(() => { laterCalled = true; });
let caught: unknown;
try { throwing.select("x"); } catch (error) { caught = error; }
assert(caught === marker, "listener exception propagates");
equal(laterCalled, false, "listener exception stops notification pass");

const resetTree = new OutlineTree([{ id: "old", label: "Old", kind: "folder", children: [{ id: "old-child", label: "Old Child", kind: "page" }] }]);
resetTree.toggle("old");
resetTree.select("old-child");
resetTree.replace([{ id: "new", label: "New", kind: "page" }]);
rows = resetTree.visibleRows();
equal(rows.length, 1, "replace installs new hierarchy");
row(rows[0], "new", "New", "page", 0, false, false);
equal(resetTree.toggle("old"), false, "replace removes old IDs");

expectTypeError(() => { new OutlineTree([{ id: "   ", label: "Blank", kind: "page" }]); }, "blank ID is rejected");
expectTypeError(() => { new OutlineTree([{ id: "dup", label: "A", kind: "page" }, { id: "dup", label: "B", kind: "page" }]); }, "duplicate ID is rejected");
const cyclic: { id: string; label: string; kind: string; children?: OutlineNode[] } = { id: "cycle", label: "Cycle", kind: "folder" };
cyclic.children = [cyclic];
expectTypeError(() => { new OutlineTree([cyclic]); }, "cyclic object reference is rejected");

